// Muscle groups: a front/back gorilla figure, the exercise card, the dashboard statistics and the editor picker.
// The muscle outlines are in muscle-figure.js (generated by tools/build_muscle_figure.py).
const Muscles = (() => {
  let taxonomy = null;
  let loading = null;

  // Which muscle keys colour a drawn muscle. A muscle without an entry is only part of the silhouette.
  const LIGHTS = {
    front: {
      obliques: ['core'], abs: ['core'], biceps: ['biceps'], triceps: ['triceps'], trapezius: ['traps'], neck: ['neck'],
      deltoids: ['shoulder_front', 'shoulder_side'], adductors: ['adductors'], quadriceps: ['quads'],
      tibialis: ['tibialis', 'calves'], calves: ['calves'], forearm: ['forearms'],
    },
    back: {
      trapezius: ['traps'], neck: ['neck'], deltoids: ['shoulder_rear', 'shoulder_side', 'rotator_cuff'], 'upper-back': ['lats', 'mid_back'],
      triceps: ['triceps'], 'lower-back': ['lower_back'], forearm: ['forearms'], gluteal: ['glutes', 'abductors'],
      adductors: ['adductors'], hamstring: ['hamstrings'], calves: ['calves'],
    },
  };
  // The chest is cut in three bands so an incline or decline exercise lights only its own part.
  const CHEST_BANDS = [
    { keys: ['chest_upper', 'chest'], from: 300, to: 352 },
    { keys: ['chest'], from: 352, to: 392 },
    { keys: ['chest_lower', 'chest'], from: 392, to: 450 },
  ];

  const VIEW_BOX = '-345 85 1380 1075';
  const groupOf = key => taxonomy?.muscles.find(muscle => muscle.key === key)?.group || null;
  const label = key => taxonomy?.muscles.find(muscle => muscle.key === key)?.label || key;
  const labels = keys => keys.map(label).join(', ');

  function headMarkup(view) {
    const ears = '<ellipse class="mb-head" cx="-72" cy="243" rx="11" ry="20"/><ellipse class="mb-head" cx="72" cy="243" rx="11" ry="20"/>';
    const skull = '<path class="mb-head" d="M-30 152C-20 116 20 116 30 152Z"/>'
      + '<path class="mb-head" d="M-64 236C-70 190 -52 150 -26 136C-12 128 12 128 26 136C52 150 70 190 64 236C66 280 40 314 0 316C-40 314 -66 280 -64 236Z"/>';
    const wrap = inner => `<g transform="translate(0 250) scale(1.15) translate(0 -250)">${inner}</g>`;
    if (view === 'back') return wrap(ears + skull + '<path class="mb-line" d="M-28 270Q0 284 28 270M0 150V200"/>');
    return wrap(ears + skull
      + '<path class="mb-face" d="M-46 232C-40 214 40 214 46 232C52 268 36 300 0 302C-36 300-52 268-46 232Z"/>'
      + '<path class="mb-brow" d="M-54 224C-28 208 28 208 54 224L52 242C26 232-26 232-52 242Z"/>'
      + '<ellipse class="mb-eye" cx="-22" cy="246" rx="7" ry="4.5"/><ellipse class="mb-eye" cx="22" cy="246" rx="7" ry="4.5"/>'
      + '<ellipse class="mb-muzzle" cx="0" cy="280" rx="32" ry="24"/>'
      + '<ellipse class="mb-dark" cx="-9" cy="274" rx="5" ry="3.5"/><ellipse class="mb-dark" cx="9" cy="274" rx="5" ry="3.5"/>'
      + '<path class="mb-line" d="M-20 293Q0 300 20 293"/>');
  }

  // options: { primary: [keys], secondary: [keys] } for an exercise, or { heat: { group: 0..1 }, tips: { group: text } } for statistics.
  function figure({ primary = [], secondary = [], heat = null, tips = {} } = {}) {
    const stateOf = keys => {
      if (heat) {
        // A region that belongs to several groups (e.g. the glutes also carry the abductors) shows the busiest one.
        const groups = [...new Set(keys.map(groupOf).filter(Boolean))];
        const group = groups.reduce((best, item) => ((heat[item] || 0) > (heat[best] || 0) ? item : best), groups[0]);
        const value = group ? heat[group] || 0 : 0;
        return value > 0 ? { kind: 'heat', value, tip: `${group}: ${tips[group] || ''}` } : null;
      }
      const first = keys.filter(key => primary.includes(key));
      if (first.length) return { kind: 'p', tip: `${labels(first)} · primair` };
      const second = keys.filter(key => secondary.includes(key));
      if (second.length) return { kind: 's', tip: `${labels(second)} · secundair` };
      return null;
    };
    const classOf = state => !state ? 'mb-shape' : `mb-shape mb-${state.kind}`;
    const styleOf = state => state?.kind === 'heat' ? ` style="fill-opacity:${(0.3 + state.value * 0.7).toFixed(2)}"` : '';
    const attributes = state => `class="${classOf(state)}"${styleOf(state)}${state ? ` data-tip="${escapeHtml(state.tip)}"` : ''}`;

    let clipId = 0;
    const views = ['front', 'back'].map((view, index) => {
      const lights = LIGHTS[view];
      const body = MUSCLE_FIGURE[view].map(shape => {
        if (shape.s === 'chest') {
          const states = CHEST_BANDS.map(band => stateOf(band.keys));
          const same = states.every(state => state?.kind === states[0]?.kind && state?.value === states[0]?.value);
          if (same) return `<path d="${shape.d}" ${attributes(states[0])}/>`;
          let markup = `<path d="${shape.d}" class="mb-shape"/>`;
          CHEST_BANDS.forEach((band, bandIndex) => {
            if (!states[bandIndex]) return;
            const id = `mbclip${clipId++}`;
            markup += `<clipPath id="${id}"><rect x="-400" y="${band.from}" width="800" height="${band.to - band.from}"/></clipPath>`
              + `<path d="${shape.d}" clip-path="url(#${id})" ${attributes(states[bandIndex])}/>`;
          });
          return markup;
        }
        const keys = lights[shape.s];
        return `<path d="${shape.d}" ${attributes(keys ? stateOf(keys) : null)}/>`;
      }).join('');
      return `<g transform="translate(${index * 700} 0)">${body}${headMarkup(view)}`
        + `<text x="0" y="1140" class="mb-label">${view === 'front' ? 'VOOR' : 'ACHTER'}</text></g>`;
    }).join('');
    return `<div class="mb-wrap"><svg class="muscle-figure" viewBox="${VIEW_BOX}" role="img" aria-label="Spiergroepen, voor- en achterkant">${views}</svg>`
      + '<div class="mb-tip" role="status" aria-live="polite">Tik op een spier voor details</div></div>';
  }

  // Tapping a muscle names it under the figure.
  document.addEventListener('click', event => {
    const wrap = event.target.closest?.('.mb-wrap');
    if (!wrap) return;
    const shape = event.target.closest('[data-tip]');
    wrap.querySelectorAll('.mb-selected').forEach(item => item.classList.remove('mb-selected'));
    if (shape) shape.classList.add('mb-selected');
    wrap.querySelector('.mb-tip').textContent = shape ? shape.dataset.tip : 'Tik op een spier voor details';
  });

  function load() {
    loading ||= api('/api/muscles').then(data => { taxonomy = data; return data; }).catch(error => { loading = null; throw error; });
    return loading;
  }

  // Chips to choose primary and secondary muscles of one exercise in the schema editor.
  function picker(index, primary, secondary) {
    const row = (kind, selected, title) => `<div class="muscle-pick"><span>${title}</span><div class="chip-row">${
      (taxonomy?.muscles || []).map(muscle => `<button type="button" class="chip${selected.includes(muscle.key) ? ' active' : ''}"
        aria-pressed="${selected.includes(muscle.key)}" onclick="toggleDraftMuscle(${index}, '${kind}', '${muscle.key}')">${escapeHtml(muscle.label)}</button>`).join('')
    }</div></div>`;
    return row('primary', primary, 'Primair (telt mee in statistieken)') + row('secondary', secondary, 'Secundair');
  }

  return { load, figure, label, labels, picker, get ready() { return Boolean(taxonomy); } };
})();

// Cards that use the figure: the exercise card on the Training tab and the statistics card on the dashboard.
const MuscleUI = (() => {
  let period = 'week';
  let request = 0;

  function showExercise(exercise) {
    const card = document.getElementById('muscleCard');
    if (!card) return;
    if (!exercise) { card.hidden = true; return; }
    const primary = exercise.primary_muscles || [];
    const secondary = exercise.secondary_muscles || [];
    const body = primary.length || secondary.length
      ? `<div><span class="muscle-kind p">Primair</span> ${escapeHtml(Muscles.labels(primary) || '–')}</div>
         ${secondary.length ? `<div><span class="muscle-kind s">Secundair</span> ${escapeHtml(Muscles.labels(secondary))}</div>` : ''}`
      : `<div class="text-muted">Spiergroep nog niet ingesteld.</div>
         <button type="button" class="btn btn-ghost btn-sm" onclick="openRoutineEditor()">Instellen</button>`;
    card.innerHTML = `${Muscles.figure({ primary, secondary })}<div class="muscle-copy">${body}</div>`;
    card.hidden = false;
  }

  function selectPeriod(button) {
    period = button.dataset.period;
    document.querySelectorAll('#musclePeriod .chip').forEach(chip => chip.classList.toggle('active', chip === button));
    loadStats();
  }

  const nl = value => Number(value).toLocaleString('nl-NL');
  const PERIODS = [['week', 'Deze week'], ['month', 'Deze maand'], ['12w', '12 weken'], ['all', 'Alles']];
  const shortDate = iso => new Date(`${iso}T00:00:00`).toLocaleDateString('nl-NL', { day: 'numeric', month: 'short', year: '2-digit' });

  function groupSheet(data) {
    const peak = Math.max(...data.weekly.map(week => week.volume), 1);
    const weekly = data.weekly.map(week => `<span class="gw-bar" title="Week van ${shortDate(week.start)}: ${nl(week.volume)} kg">
      <i style="height:${Math.max(3, Math.round(week.volume / peak * 100))}%"></i></span>`).join('');
    const exercises = data.exercises.length ? data.exercises.map(item => `<div class="gx-row">
        <div><strong>${escapeHtml(item.name)}</strong>${item.prs ? `<span class="ss-pr">🏆 ${item.prs}</span>` : ''}
          <small>${item.sets} sets in ${item.sessions} ${item.sessions === 1 ? 'training' : 'trainingen'} · laatst ${shortDate(item.last_date)}</small></div>
        <div class="gx-side"><b>${nl(item.volume)} kg</b>${item.record
          ? `<small>Record ${nl(item.record.weight)} kg × ${item.record.reps} (${shortDate(item.record.date)})</small>` : ''}</div>
      </div>`).join('') : '<div class="empty-state"><p>Geen sets in deze periode.</p></div>';
    const prs = data.recent_prs.length ? `<h3>Recente PR's</h3>${data.recent_prs.map(pr =>
      `<div class="gx-pr"><span>🏆 ${escapeHtml(pr.name)}</span><b>${nl(pr.weight)} kg × ${pr.reps}</b><small>${shortDate(pr.date)}</small></div>`).join('')}` : '';
    const supporting = data.supporting.length ? `<h3>Ondersteunend bij</h3><p class="text-muted">${data.supporting.map(escapeHtml).join(', ')}</p>` : '';
    return `<div class="chip-row">${PERIODS.map(([id, name]) =>
        `<button type="button" class="chip${id === data.period ? ' active' : ''}" data-group-period="${id}" data-group="${escapeHtml(data.group)}">${name}</button>`).join('')}</div>
      <div class="cd-stats"><div><span>Volume</span><strong>${nl(data.total_volume)} kg</strong></div><div><span>Sets</span><strong>${data.total_sets}</strong></div>
        <div><span>Oefeningen</span><strong>${data.exercises.length}</strong></div></div>
      <h3>Volume per week (12 weken)</h3><div class="gw-bars">${weekly}</div>
      <h3>Oefeningen</h3>${exercises}${prs}${supporting}`;
  }

  async function openGroup(group, groupPeriod = period) {
    try {
      const data = await api(`/api/muscle-groups/${encodeURIComponent(group)}?period=${groupPeriod}`);
      Sheet.open(group, groupSheet(data));
    } catch (error) {
      toast(error.message);
    }
  }

  Sheet.element().addEventListener('click', event => {
    const chip = event.target.closest('[data-group-period]');
    if (chip) openGroup(chip.dataset.group, chip.dataset.groupPeriod);
  });
  document.addEventListener('click', event => {
    const row = event.target.closest('.muscle-row[data-group]');
    if (row) openGroup(row.dataset.group);
  });

  async function loadStats() {
    const container = document.getElementById('muscleStats');
    if (!container) return;
    const current = ++request;
    try {
      const [data] = await Promise.all([api(`/api/muscles/stats?period=${period}`), Muscles.load()]);
      if (current !== request) return;
      const heat = Object.fromEntries(data.groups.map(group => [group.group, group.relative]));
      const tips = Object.fromEntries(data.groups.map(group => [group.group, `${nl(group.volume)} kg · ${group.sets} sets`]));
      const rows = [...data.groups].sort((a, b) => b.volume - a.volume || b.sets - a.sets);
      const peak = Math.max(...rows.map(row => row.volume), 0);
      const list = peak
        ? rows.map(row => `<button type="button" class="muscle-row${row.volume ? '' : ' none'}" data-group="${escapeHtml(row.group)}">
            <div class="muscle-row-head"><span>${escapeHtml(row.group)} ›</span><span>${nl(row.volume)} kg · ${row.sets} sets</span></div>
            <div class="muscle-bar"><span style="width:${peak ? Math.round(row.volume / peak * 100) : 0}%"></span></div>
          </button>`).join('')
        : '<div class="empty-state"><p>Nog geen sets in deze periode.</p></div>';
      const unassigned = data.unassigned.sets
        ? `<p class="text-muted">${data.unassigned.sets} sets horen bij oefeningen zonder spiergroep.</p>` : '';
      container.innerHTML = `<div class="muscle-stats">${Muscles.figure({ heat, tips })}<div class="muscle-list">${list}</div></div>${unassigned}`;
    } catch (error) {
      if (current === request) container.innerHTML = '<div class="empty-state"><p>Spiergroepen konden niet laden.</p></div>';
    }
  }

  return { showExercise, selectPeriod, loadStats };
})();
